CREATE FUNCTION airlinerra_game.section9_verified_berlin_game_hour_v1() RETURNS jsonb LANGUAGE sql AS $$SELECT '{"authoritativeGameHourAvailable":true,"gameHourUtc":"2026-11-27T12:00:00Z"}'::jsonb$$;
CREATE FUNCTION airlinerra_game.section9_auto_disruption_cycle_v1(int) RETURNS jsonb LANGUAGE sql AS $$SELECT '{"status":"fixture"}'::jsonb$$;
CREATE FUNCTION airlinerra_game.section9_auto_recover_delayed_crew_cycle_v1(int) RETURNS jsonb LANGUAGE sql AS $$SELECT '{"status":"fixture"}'::jsonb$$;
CREATE FUNCTION airlinerra_game.section9_auto_replan_downstream_cycle_v1(int) RETURNS jsonb LANGUAGE sql AS $$SELECT '{"status":"fixture"}'::jsonb$$;
CREATE FUNCTION airlinerra_game.section9_effective_dispatch_window_v1(uuid) RETURNS TABLE(effective_departure_utc timestamptz,effective_arrival_utc timestamptz,is_delayed boolean,dispatch_allowed boolean) LANGUAGE sql AS $$SELECT departure_utc,arrival_utc,false,true FROM airlinerra_game.section9_dated_flight_occurrences_v1 WHERE id=$1$$;
CREATE FUNCTION airlinerra_game.section9_disruption_departure_clear_v1(uuid) RETURNS boolean LANGUAGE sql AS $$SELECT true$$;
CREATE FUNCTION airlinerra_game.section9_automatic_disruption_ready_v1() RETURNS boolean LANGUAGE sql AS $$SELECT true$$;
CREATE FUNCTION airlinerra_game.section9_canonical_aoc_covers_v1(uuid,date,int) RETURNS boolean LANGUAGE sql AS $$SELECT true$$;
CREATE FUNCTION airlinerra_game.section9_verified_permission_game_day_v1() RETURNS date LANGUAGE sql AS $$SELECT DATE '2026-11-27'$$;
CREATE FUNCTION airlinerra_game.section9_game_route_licence_scope_v1(uuid,text,text,date,int) RETURNS jsonb LANGUAGE sql AS $$SELECT '{"allowed":true}'::jsonb$$;
CREATE FUNCTION airlinerra_game.section9_delayed_turnaround_clear_v1(uuid,uuid,timestamptz) RETURNS boolean LANGUAGE sql AS $$SELECT true$$;
CREATE FUNCTION airlinerra_game.section9_verified_game_maintenance_dispatch_window_v1(uuid,uuid,uuid,timestamptz,timestamptz) RETURNS jsonb LANGUAGE sql AS $$SELECT '{"gameMaintenanceClear":true}'::jsonb$$;
CREATE FUNCTION airlinerra_game.section9_auto_supply_game_only_fuel_v1(text) RETURNS jsonb LANGUAGE plpgsql AS $$BEGIN INSERT INTO airlinerra_game.test_dispatch_effects VALUES('fuel');RETURN '{"status":"game_fuel_already_sufficient","ledgerPosted":false}'::jsonb;END$$;
CREATE FUNCTION airlinerra_game.section9_verify_game_fuel_before_departure_v1(text) RETURNS jsonb LANGUAGE sql AS $$SELECT '{"status":"verified_game_fuel_onboard_available_for_planned_trip","fuelVerifiedForGame":true,"ledgerPosted":false}'::jsonb$$;
CREATE FUNCTION airlinerra_game.section9_operated_day_candidates_for_aircraft_v1(uuid,uuid,date) RETURNS jsonb LANGUAGE sql AS $$SELECT jsonb_build_object('status','verified_operational_candidates_only','candidates',jsonb_agg(jsonb_build_object('scheduleId',schedule_id,'scheduleVersion',schedule_version,'flightLocalDate',flight_local_date,'weeklyEntry',weekly_entry,'phase','departed','scheduledEventUtc',departure_utc,'eventId','SYNTHETIC-DISPATCH-0001'))) FROM airlinerra_game.section9_dated_flight_occurrences_v1$$;
CREATE FUNCTION airlinerra_game.section9_downstream_crew_reconciliation_v1(uuid,uuid) RETURNS jsonb LANGUAGE sql AS $$SELECT jsonb_build_object('status',CASE WHEN mode='downstream' THEN 'downstream_crew_reconciled' ELSE 'downstream_unaffected' END) FROM airlinerra_game.test_dispatch_mode$$;
CREATE FUNCTION airlinerra_game.section9_check_delayed_crew_binding_v1(uuid,uuid,timestamptz) RETURNS jsonb LANGUAGE sql AS $$SELECT '{"status":"delayed_crew_binding_ready"}'::jsonb$$;
CREATE FUNCTION airlinerra_game.storage_commercial_handoff_dispatch_check_v1(uuid,text) RETURNS jsonb LANGUAGE sql AS $$SELECT CASE mode WHEN 'ordinary' THEN '{"allowed":true,"status":"no_storage_handoff_conflict"}'::jsonb WHEN 'custody' THEN '{"allowed":false,"status":"storage_crew_custody_conflict"}'::jsonb ELSE '{"allowed":false,"status":"storage_handoff_dispatch_integration_required"}'::jsonb END FROM airlinerra_game.test_dispatch_mode$$;
CREATE FUNCTION airlinerra_game.section9_record_signed_operated_flight_movement_v1(uuid,uuid,int,date,int,text,timestamptz,text,text) RETURNS jsonb LANGUAGE plpgsql AS $$BEGIN INSERT INTO airlinerra_game.section9_operated_flight_movements_v1 VALUES($2::text||':'||$4||':'||$5,$6,$8);RETURN '{"movementRecorded":true,"replayed":false,"ledgerPosted":false}'::jsonb;END$$;
CREATE FUNCTION airlinerra_game.section9_capture_verified_departure_fuel_v1(text,text) RETURNS jsonb LANGUAGE plpgsql AS $$BEGIN INSERT INTO airlinerra_game.test_dispatch_effects VALUES('receipt');RETURN '{"status":"signed_game_fuel_departure_receipt_created","fuelReceiptCreated":true,"ledgerPosted":false}'::jsonb;END$$;
CREATE FUNCTION airlinerra_game.section9_capture_dispatched_crew_v1(uuid,text,text) RETURNS jsonb LANGUAGE plpgsql AS $$BEGIN INSERT INTO airlinerra_game.test_dispatch_effects VALUES('legacy');RETURN '{"status":"crew_departure_bound"}'::jsonb;END$$;
CREATE FUNCTION airlinerra_game.bind_storage_aware_commercial_departure_v1(uuid,text,text) RETURNS jsonb LANGUAGE plpgsql AS $$BEGIN INSERT INTO airlinerra_game.test_dispatch_effects VALUES('storage');IF EXISTS(SELECT 1 FROM airlinerra_game.test_dispatch_mode WHERE mode='binding_failed') THEN RETURN '{"status":"fixture_rejected"}'::jsonb;END IF;RETURN '{"status":"crew_departure_bound"}'::jsonb;END$$;
